const e=["Dieu","Marchés","Commerce","Religion","Force"],t="Tout a un prix. Mais tout n'a pas la même valeur.",n="Dieu des Marchés",r=["Othar représente les Marchés.","Il ne s'intéresse pas uniquement aux pièces et aux marchandises.","Tout peut faire l'objet d'un échange :","une épée contre de l'or,","un service contre une faveur,","une information contre un secret,","une promesse contre une autre promesse.","Pour Othar, le commerce révèle ce que les mortels considèrent réellement comme précieux."],s=[{label:"Domaines",value:"Marchés, Échanges"},{label:"Symboles",value:"Une balance, deux pièces, une bourse, une main échangeant un objet, une caravane, une porte ouverte, un comptoir de marchand"}],a=[{title:"La valeur",title_border:"#e8553d",type:"text",content:["La valeur d'une chose n'est jamais entièrement objective.","Un morceau de pain peut ne presque rien valoir dans une ville prospère et devenir inestimable après plusieurs jours de famine.","Une vieille lettre peut être sans valeur pour un marchand et représenter toute une vie pour celui qui la reçoit.","Othar représente cette différence entre le prix d'une chose et sa véritable valeur."]},{title:"L'échange",title_border:"#c2660a",type:"text",content:["Le commerce crée des liens entre des peuples qui ne partageraient autrement rien.","Les marchandises voyagent.","Les idées voyagent avec elles.","Les langues, les traditions et les connaissances peuvent également circuler par les routes commerciales.","C'est pourquoi Othar est parfois considéré comme un dieu des rencontres autant que des marchands."]},{title:"Le marché",title_border:"#6f9fd8",type:"text",content:["Les marchés consacrés à Othar sont rarement de véritables temples.","Ce sont souvent des places publiques, des halles ou des carrefours où les marchands peuvent travailler.","Certains commerçants déposent une pièce dans un petit sanctuaire avant leur première vente de la journée.","D'autres demandent simplement à Othar que leur parole soit entendue et leur marchandise honnêtement évaluée."]},{title:"Le contrat",title_border:"#e8553d",type:"text",content:["Les contrats occupent une place importante dans les traditions d'Othar.","Une promesse faite devant son symbole est considérée comme particulièrement sérieuse.","Mais Othar ne garantit pas qu'un contrat soit juste.","Il garantit seulement que l'échange a été accepté.","Cette distinction explique pourquoi certains contrats associés à son culte sont réputés aussi dangereux que des pactes."]},{title:"Othar et Théomis",title_border:"#c2660a",type:"text",content:["Othar entretient une relation naturelle avec Théomis, dieu de l'Ordre.","Le commerce nécessite des règles.","Poids, mesures, monnaies, contrats et frontières doivent être suffisamment stables pour permettre les échanges.","Mais Othar rappelle également que trop de règles peuvent étouffer le marché.","L'Ordre permet au commerce d'exister.","Le commerce, lui, oblige parfois l'Ordre à s'adapter."]},{title:"Othar et Phiella",title_border:"#6f9fd8",type:"text",content:["La relation avec Phiella est plus ambiguë.","La Tentation peut prendre la forme d'une offre commerciale particulièrement avantageuse.","Un marchand peut proposer richesse, pouvoir ou information en échange de quelque chose que l'on aurait normalement refusé de donner.","Les deux cultes se retrouvent ainsi souvent dans les mêmes histoires.","Mais là où Phiella s'intéresse au choix du mortel, Othar s'intéresse à l'échange qui en résulte."]},{title:"Symboles",title_border:"#e8553d",type:"text",content:"Othar est généralement représenté par :"},{title:"",type:"list",content:["Une balance","Deux pièces","Une bourse","Une main échangeant un objet","Une caravane","Une porte ouverte","Un comptoir de marchand"]},{title:"",type:"text",content:["La balance est son symbole le plus répandu.","Elle représente moins la Justice que la comparaison des valeurs."]},{title:"Aujourd'hui",title_border:"#c2660a",type:"text",content:["Othar est particulièrement vénéré dans les grandes villes, les ports et les régions traversées par les routes commerciales.","Son influence dépasse cependant largement les marchands.","Voyageurs, artisans, négociateurs, diplomates et intermédiaires peuvent également lui rendre hommage.","Une vieille maxime lui est souvent attribuée :"]}],i=["Les Dieux","Théomis","Phiella","Commerce","Marchés","Religion"],o={tags:e,citation:t,surname:n,presentation:r,infos:s,sections:a,related:i};export{t as citation,o as default,s as infos,r as presentation,i as related,a as sections,n as surname,e as tags};
